declare const callNative: any;

export interface LocaleObject {
  [key: string]: string; // Add index signature
}

export enum ContainerType {
  weex = "weex",
  web = "web"
}

export function getContainerType(): string {
  let type = "";
  if (typeof callNative === "function") {
    // eslint-disable-line
    type = ContainerType.weex;
  } else if (
    typeof navigator === "object" &&
    (navigator.appCodeName === "Mozilla" || navigator.product === "Gecko")
  ) {
    type = ContainerType.web;
  }
  return type;
}

export function splitOnFirst(str: string, separator: string): string[] {
  if (separator === "") {
    return [str];
  }

  const separatorIndex = str.indexOf(separator);

  if (separatorIndex === -1) {
    return [str];
  }

  return [
    str.slice(0, separatorIndex),
    str.slice(separatorIndex + separator.length)
  ];
}
export function decode(str: string): string {
  try {
    return decodeURIComponent(str);
  } catch (error) {
    return str;
  }
}
export function encode(str: string): string {
  try {
    return encodeURIComponent(str);
  } catch (error) {
    return str;
  }
}

export function parseQueryString(str: string): LocaleObject {
  if(!str) return {};
  const keysAndValue = str.split("&");
  const localeObject: LocaleObject = {};
  keysAndValue.forEach(
    (el): void => {
      const [key, value] = splitOnFirst(el.replace(/\+/g, " "), "=");
      const decodeValue = value === undefined ? "" : decode(value);
      localeObject[key] = decodeValue;
    }
  );
  return localeObject;
}

export function stringifyToQueryString(object: LocaleObject): string {
  const keys = Object.keys(object);
  const str = keys
    .map(
      (key): string => {
        const value = object[key];

        if (value === undefined) {
          return "";
        }

        if (value === null) {
          return encode(key);
        }
        const itemStr = `${encode(key)}=${encode(value)}`;
        return itemStr;
      }
    )
    .filter((x): boolean => x.length > 0)
    .join("&");
  return str;
}

export function objectValues(obj: { [key: string]: string }): any[] {
  const vals: any[] = [];
  for (let key in obj) {  // eslint-disable-line
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      vals.push(obj[key]);
    }
  }
  return vals;
}
